document.querySelector('.photo-credit')?.remove();
const hero=document.querySelector('section.hero');hero.classList.remove('drive-hero');hero.classList.add('text-hero');
const heroTitle=lang==='hu'?'<span>Tedd könnyebbé,</span><span>hogy rád találjanak</span><span class="hero-city">Budapesten.</span>':'<span>Make it easier</span><span>for people to find</span><span>your business</span><span class="hero-city">in Budapest.</span>';
