hero.innerHTML=`<div class="hero-text-column"><p class="hero-brandline">LOKMIRA · BUDAPEST</p><h1 id="hero-title">${heroTitle}</h1><p class="hero-description">${heroDescription}</p><div class="hero-actions"><a class="button primary" href="#contact"><span>${c.heroCTA}</span><span class="landing-icon icon-arrow-up-right" aria-hidden="true"></span></a><a class="text-link" href="#services"><span>${c.heroSecondary}</span><span class="landing-icon icon-arrow-right icon-down" aria-hidden="true"></span></a></div><div class="hero-notes"></div></div><div class="hero-source-column"><picture class="hero-source-picture"><source srcset="${assetRoot}hero-banner-${lang}.webp" type="image/webp"><img src="${assetRoot}hero-banner-${lang}.webp" alt="${lang==='hu'?'A Lokmira budapesti helyi keresési koncepciója. A számok és az űrlap szemléltető elemek.':'Lokmira’s Budapest local search concept. Figures and the form are illustrative.'}" width="1672" height="941" fetchpriority="high"></picture></div>`;
document.documentElement.lang=lang;document.title=c.title;document.querySelector('meta[name="description"]').content=c.description;document.querySelector('link[rel="canonical"]').href=lang==='hu'?'https://lokmira.com/':'https://lokmira.com/en/';document.querySelectorAll('[data-t]').forEach(el=>{el.textContent=c[el.dataset.t]??el.textContent});document.querySelectorAll('[data-alt]').forEach(el=>{el.alt=c[el.dataset.alt]});document.querySelectorAll('[data-lang]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.lang===lang)));document.querySelectorAll('[data-route]').forEach(el=>el.href='/'+routes[lang][el.dataset.route]);document.querySelector('#navigation').setAttribute('aria-label',lang==='hu'?'Fő navigáció':'Main navigation');document.querySelector('.menu').setAttribute('aria-label',c.menuOpen);document.querySelector('.about-mark span').innerHTML=lang==='hu'?'LOKÁLIS FÓKUSZ.<br>TISZTA IRÁNY.':'LOCAL FOCUS.<br>CLEAR DIRECTION.';
